create table public.identitystore_ref_attribute
(
    id_attribute                 serial
        primary key,
    name                         varchar(100) default ''::character varying                                                                                    not null
        unique,
    key_name                     varchar(100) default ''::character varying                                                                                    not null
        unique,
    description                  varchar(255),
    key_type                     integer      default 0                                                                                                        not null,
    key_weight                   integer      default 0                                                                                                        not null,
    certifiable                  smallint     default 0,
    pivot                        smallint     default 0,
    common_search_key            varchar(100),
    mandatory_for_creation       smallint     default 0                                                                                                        not null,
    validation_regex             varchar(510) default '^[A-Za-zÀ-Üà-ü\d\s''-]+$'::character varying,
    validation_error_message     varchar(255) default 'Only alphanim chars, apostrophe, space and dash.'::character varying,
    validation_error_message_key varchar(255) default 'identitystore.attribute.status.validation.error.only.alphanum.apostrophe.space.dash'::character varying not null
);

alter table public.identitystore_ref_attribute
    owner to idstore;

create table public.identitystore_duplicate_rule_attribute_treatment_nuples
(
    id_attribute_treatment integer
        constraint fk_duplicate_rule_attribute_treatment_nuples_id_rule
            references public.identitystore_duplicate_rule_attribute_treatment
            on delete cascade,
    id_attribute           integer
        constraint fk_duplicate_rule_attribute_treatment_nuples_id_attribute
            references public.identitystore_ref_attribute
);

alter table public.identitystore_duplicate_rule_attribute_treatment_nuples
    owner to idstore;

create table public.identitystore_duplicate_rule_checked_attributes
(
    id_rule      integer
        constraint fk_duplicate_rule_checked_attributes_id_rule
            references public.identitystore_duplicate_rule
            on delete cascade,
    id_attribute integer
        constraint fk_duplicate_rule_checked_attributes_id_attribute
            references public.identitystore_ref_attribute
);

alter table public.identitystore_duplicate_rule_checked_attributes
    owner to idstore;

create table public.identitystore_identity_attribute
(
    id_identity       integer      default 0                 not null
        constraint fk_identity_attribute_id_identity
            references public.identitystore_identity,
    id_attribute      integer      default 0                 not null
        constraint fk_identity_attribute_id_attribute
            references public.identitystore_ref_attribute,
    attribute_value   text,
    id_certification  integer      default 0                 not null,
    id_file           integer      default 0,
    lastupdate_date   timestamp(3) default CURRENT_TIMESTAMP not null,
    lastupdate_client varchar(100),
    primary key (id_identity, id_attribute)
);

alter table public.identitystore_identity_attribute
    owner to idstore;

create index ix_attribute_value
    on public.identitystore_identity_attribute (attribute_value);

create table public.identitystore_identity_search_rule_attribute
(
    id_rule      integer not null
        constraint fk_identity_search_rule_attribute_id_rule
            references public.identitystore_identity_search_rule
            on delete cascade,
    id_attribute integer not null
        constraint fk_identity_search_rule_attribute_id_attribute
            references public.identitystore_ref_attribute
);

alter table public.identitystore_identity_search_rule_attribute
    owner to idstore;

create table public.identitystore_ref_attribute_values
(
    id_attribute integer
        constraint fk_id_attribute
            references public.identitystore_ref_attribute,
    value        varchar(50),
    label        varchar(255)
);

alter table public.identitystore_ref_attribute_values
    owner to idstore;

create table public.identitystore_ref_certification_processus
(
    id_ref_attribute_certification_processus serial
        primary key,
    label                                    varchar(50) default ''::character varying not null,
    code                                     varchar(50) default ''::character varying not null
);

alter table public.identitystore_ref_certification_processus
    owner to idstore;

create table public.identitystore_ref_certification_level
(
    id_ref_certification_level serial
        primary key,
    name                       varchar(255) default ''::character varying,
    description                varchar(255) default ''::character varying,
    level                      varchar(50)  default ''::character varying not null
);

alter table public.identitystore_ref_certification_level
    owner to idstore;

create table public.identitystore_ref_certification_attribute_level
(
    id_attribute                             integer not null
        constraint fk_attribute_ref_certification_level_id_attribute
            references public.identitystore_ref_attribute,
    id_ref_certification_level               integer not null
        constraint fk_attribute_ref_certification_level_certification_level
            references public.identitystore_ref_certification_level,
    id_ref_attribute_certification_processus integer not null
        constraint fk_attribute_ref_certification_level_certification_processus
            references public.identitystore_ref_certification_processus,
    primary key (id_attribute, id_ref_certification_level, id_ref_attribute_certification_processus)
);

alter table public.identitystore_ref_certification_attribute_level
    owner to idstore;

create table public.identitystore_service_contract
(
    id_service_contract             serial
        primary key,
    id_client_app                   integer                                    not null
        constraint fk_service_contract_id_client_app
            references public.identitystore_client_application,
    name                            varchar(255) default ''::character varying not null,
    organizational_entity           varchar(50)  default ''::character varying not null,
    moa_entity_name                 varchar(255) default ''::character varying not null,
    moa_responsible_name            varchar(255) default ''::character varying not null,
    moa_contact_name                varchar(255) default ''::character varying not null,
    moe_entity_name                 varchar(255) default ''::character varying not null,
    moe_responsible_name            varchar(255) default ''::character varying not null,
    contact_name                    varchar(50)  default ''::character varying not null,
    service_type                    varchar(255) default ''::character varying not null,
    starting_date                   date                                       not null,
    ending_date                     date,
    data_retention_period_in_months integer                                    not null,
    authorized_creation             smallint     default 0                     not null,
    authorized_update               smallint     default 0                     not null,
    authorized_deletion             smallint     default 0                     not null,
    authorized_search               smallint     default 0                     not null,
    authorized_import               smallint     default 0                     not null,
    authorized_export               smallint     default 0                     not null,
    authorized_merge                smallint     default 0                     not null,
    authorized_account_update       smallint     default 0                     not null,
    authorized_decertification      smallint     default 0                     not null,
    authorized_agent_history_read   smallint     default 0                     not null
);

alter table public.identitystore_service_contract
    owner to idstore;

create table public.identitystore_service_contract_attribute_certification
(
    id_service_contract                      integer not null
        constraint fk_attribute_certification_id_service_contract
            references public.identitystore_service_contract,
    id_attribute                             integer not null
        constraint fk_attribute_certification_id_attribute
            references public.identitystore_ref_attribute,
    id_ref_attribute_certification_processus integer not null
        constraint fk_attribute_certification_certification_processus
            references public.identitystore_ref_certification_processus,
    primary key (id_attribute, id_ref_attribute_certification_processus, id_service_contract)
);

alter table public.identitystore_service_contract_attribute_certification
    owner to idstore;

create table public.identitystore_service_contract_attribute_requirement
(
    id_service_contract        integer not null
        constraint fk_attribute_requirement_id_service_contract
            references public.identitystore_service_contract,
    id_attribute               integer not null
        constraint fk_attribute_requirement_id_attribute
            references public.identitystore_ref_attribute,
    id_ref_certification_level integer not null
        constraint fk_attribute_requirement_certification_level
            references public.identitystore_ref_certification_level,
    primary key (id_attribute, id_service_contract, id_ref_certification_level)
);

alter table public.identitystore_service_contract_attribute_requirement
    owner to idstore;

create table public.identitystore_service_contract_attribute_right
(
    id_service_contract integer            not null
        constraint fk_attribute_right_id_service_contract
            references public.identitystore_service_contract,
    id_attribute        integer            not null
        constraint fk_attribute_right_id_attribute
            references public.identitystore_ref_attribute,
    searchable          smallint default 0 not null,
    readable            smallint default 0 not null,
    writable            smallint default 0 not null,
    mandatory           smallint default 0 not null,
    primary key (id_service_contract, id_attribute)
);

alter table public.identitystore_service_contract_attribute_right
    owner to idstore;

